import { Controller, HttpCode, Post, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 결재 상태 값은 공통 결정 '결재 진행 상태'와 같다.
const PLAN_STATUSES = ['기안', '결재대기', '진행중', '승인', '보류', '반려', '회수', '완료'];

@Controller('api/v1')
export class FnSfr03204Controller {
  @Post('/annual-leave-plans/:annualLeavePlanId/submit')
  @HttpCode(200)
  async submitAnnualLeavePlan(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const planId = req.params['annualLeavePlanId'];
    if (!/^[0-9]+$/.test(planId)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '연차계획 ID 형식이 올바르지 않습니다.');
    }
    return transaction(async (db) => {
      const plans = await db.query(
        `SELECT plan_status AS "planStatus", plan_month AS "planMonth"
           FROM annual_leave_plan
          WHERE annual_leave_plan_id = CAST(:planId AS bigint)`,
        { planId },
      );
      if (plans.length === 0) {
        throw new ApiError(404, 'ANNUAL_LEAVE_PLAN_NOT_FOUND', '연차계획을 찾을 수 없습니다.');
      }
      if (plans[0].planStatus !== '기안') {
        throw new ApiError(409, 'ANNUAL_LEAVE_PLAN_NOT_SUBMITTABLE', '기안 상태의 연차계획만 상신할 수 있습니다.');
      }
      // 가정: 결재양식은 사용 중인 연계 결재양식 중 첫 번째를 쓴다.
      const forms = await db.query(
        `SELECT approval_form_id AS "approvalFormId"
           FROM approval_form
          WHERE use_status = '사용' AND is_linked_approval = true
          ORDER BY approval_form_id
          LIMIT 1`,
        {},
      );
      // 가정: 기안자는 현재 사용자, 기안부서는 현재 사용자의 소속 부서다.
      const drafters = await db.query(
        `SELECT department_id AS "departmentId"
           FROM employee
          WHERE employee_id = CAST(:userId AS bigint)`,
        { userId: user.id },
      );
      if (forms.length === 0 || drafters.length === 0 || drafters[0].departmentId === null) {
        throw new ApiError(502, 'APPROVAL_LINK_FAILED', '전자결재 연계 상신에 실패했습니다.');
      }
      // 가정: 문서번호는 상신 시각과 연차계획 ID로 만든다.
      const docs = await db.query(
        `INSERT INTO approval_document (
           approval_form_id, drafter_id, drafter_department_id, document_number, title,
           approval_status, is_urgent, is_secret, linked_business_type, linked_business_id,
           submitted_at, created_at, updated_at
         ) VALUES (
           CAST(:formId AS bigint), CAST(:userId AS bigint), CAST(:departmentId AS bigint),
           'ALP-' || to_char(now(), 'YYYYMMDDHH24MISS') || '-' || CAST(:planId AS text),
           :title, '결재대기', false, false, 'annual_leave_plan', CAST(:planId AS bigint),
           now(), now(), now()
         ) RETURNING approval_document_id AS "approvalDocumentId"`,
        {
          formId: forms[0].approvalFormId,
          userId: user.id,
          departmentId: drafters[0].departmentId,
          planId,
          title: '연차계획 결재 ' + plans[0].planMonth,
        },
      );
      const approvalDocumentId = docs[0].approvalDocumentId;
      await db.execute(
        `UPDATE annual_leave_plan
            SET plan_status = '결재대기',
                approval_document_id = CAST(:docId AS bigint),
                updated_at = now()
          WHERE annual_leave_plan_id = CAST(:planId AS bigint)`,
        { docId: approvalDocumentId, planId },
      );
      return { planStatus: '결재대기', approvalDocumentId };
    });
  }

  @Post('/annual-leave-plans/approval-result')
  @HttpCode(200)
  async reflectAnnualLeavePlanApprovalResult(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원', '근태 담당자');
    const data = checks.inputOf(req.body);
    const docId = data['approvalDocumentId'];
    const planStatus = data['planStatus'];
    if (docId === undefined || docId === null || docId === '' || !/^[0-9]+$/.test(String(docId))) {
      throw new ApiError(400, 'VALIDATION_FAILED', '결재문서를 올바르게 입력해 주세요.');
    }
    if (typeof planStatus !== 'string' || !PLAN_STATUSES.includes(planStatus)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '계획 상태를 올바르게 입력해 주세요.');
    }
    return transaction(async (db) => {
      const plans = await db.query(
        `SELECT annual_leave_plan_id AS "annualLeavePlanId"
           FROM annual_leave_plan
          WHERE approval_document_id = CAST(:docId AS bigint)
          ORDER BY annual_leave_plan_id`,
        { docId: String(docId) },
      );
      if (plans.length === 0) {
        throw new ApiError(404, 'ANNUAL_LEAVE_PLAN_NOT_FOUND', '결재문서에 연결된 연차계획이 없습니다.');
      }
      await db.execute(
        `UPDATE annual_leave_plan
            SET plan_status = :planStatus, updated_at = now()
          WHERE approval_document_id = CAST(:docId AS bigint)`,
        { planStatus, docId: String(docId) },
      );
      return { annualLeavePlanId: plans[0].annualLeavePlanId, planStatus };
    });
  }
}

