import { useState } from 'react';
import { call, useData, Badge, DateText, Filters, Band, DataTable, Pager, Drawer, Form, Field, TextInput, NumberInput, DateInput, Select, LookupSelect, RefName, Tiles } from '../kit';
import type { PageProps, Row, Page } from '../kit';

const STATUS_OPTIONS: [string, string][] = [
  ['기안', '기안'],
  ['결재대기', '결재대기'],
  ['진행중', '진행중'],
  ['승인', '승인'],
  ['보류', '보류'],
  ['반려', '반려'],
  ['회수', '회수'],
  ['완료', '완료'],
];

const STAGE_OPTIONS: [string, string][] = [
  ['1차', '1차'],
  ['2차', '2차'],
];

type Mode = '' | 'create' | 'submit' | 'result' | 'promo';

export default function FnSfr03204Page({ role, notify }: PageProps) {
  const [planMonth, setPlanMonth] = useState('');
  const [applied, setApplied] = useState('');
  const [pageNo, setPageNo] = useState(0);
  const [mode, setMode] = useState<Mode>('');
  const [target, setTarget] = useState<Row | null>(null);

  const [employeeId, setEmployeeId] = useState<unknown>('');
  const [month, setMonth] = useState('');
  const [planDate, setPlanDate] = useState('');

  const [docId, setDocId] = useState<unknown>('');
  const [resultStatus, setResultStatus] = useState('');

  const [annualLeaveId, setAnnualLeaveId] = useState<unknown>('');
  const [promoEmployeeId, setPromoEmployeeId] = useState<unknown>('');
  const [stage, setStage] = useState('');
  const [noticeDate, setNoticeDate] = useState('');

  const plans = useData<Page>(
    () => call<Page>('GET', '/annual-leave-plans', role, undefined, { planMonth: applied, page: pageNo, size: 20 }),
    [role, applied, pageNo],
  );
  const promotions = useData<Page>(
    () => call<Page>('GET', '/leave-promotions', role, undefined, { page: 0, size: 5 }),
    [role],
  );

  const close = () => {
    setMode('');
    setTarget(null);
  };

  const refresh = () => {
    plans.reload();
    promotions.reload();
  };

  const createPlan = async () => {
    if (employeeId === '' || !month || !planDate) {
      throw new Error('임직원, 계획 연월, 계획 일자를 입력해 주세요.');
    }
    await call('POST', '/annual-leave-plans', role, { employeeId, planMonth: month, planDate });
    notify('연차계획을 등록했습니다.');
    close();
    refresh();
  };

  const submitPlan = async () => {
    if (!target) return;
    await call('POST', '/annual-leave-plans/' + String(target.annualLeavePlanId) + '/submit', role, {});
    notify('연차계획을 상신했습니다.');
    close();
    refresh();
  };

  const reflectResult = async () => {
    if (docId === '' || !resultStatus) {
      throw new Error('결재문서와 계획 상태를 입력해 주세요.');
    }
    await call('POST', '/annual-leave-plans/approval-result', role, { approvalDocumentId: docId, planStatus: resultStatus });
    notify('결재 결과를 반영했습니다.');
    close();
    refresh();
  };

  const createPromotion = async () => {
    if (annualLeaveId === '' || promoEmployeeId === '' || !stage || !noticeDate) {
      throw new Error('연차, 대상 임직원, 촉진 단계, 통보일을 입력해 주세요.');
    }
    await call('POST', '/leave-promotions', role, {
      annualLeaveId,
      employeeId: promoEmployeeId,
      promotionStage: stage,
      noticeDate,
    });
    notify('연차촉진을 실행했습니다.');
    close();
    refresh();
  };

  const planRows = plans.data?.items ?? [];
  const promoRows = promotions.data?.items ?? [];

  return (
    <div className={'bento'}>
      <section className={'box span-12'}>
        <h2>현황</h2>
        <Tiles items={[
          ['연차계획', <Num value={plans.data?.total ?? 0} />],
          ['연차촉진', <Num value={promotions.data?.total ?? 0} />],
        ]} />
      </section>

      <section className={'box span-8'}>
        <h2>연차계획</h2>
        <Filters
          onSearch={() => {
            setPageNo(0);
            setApplied(planMonth);
          }}
          onReset={() => {
            setPlanMonth('');
            setApplied('');
            setPageNo(0);
          }}
        >
          <Field label={'계획 연월'}>
            <TextInput value={planMonth} onChange={setPlanMonth} placeholder={'YYYY-MM'} />
          </Field>
        </Filters>
        <Band total={plans.data?.total}>
          <button type={'button'} onClick={() => setMode('create')}>연차계획 등록</button>
          <button type={'button'} onClick={() => setMode('result')}>결재 결과 반영</button>
        </Band>
        {plans.error ? <ErrorLine text={plans.error} /> : null}
        <DataTable
          rows={planRows}
          empty={'연차계획이 없습니다.'}
          columns={[
            { key: 'employeeId', label: '임직원', render: (r) => <RefName table={'employee'} role={role} value={r.employeeId} /> },
            { key: 'planMonth', label: '계획 연월' },
            { key: 'planDate', label: '계획 일자', render: (r) => <DateText value={r.planDate} /> },
            { key: 'planStatus', label: '계획 상태', render: (r) => <Badge value={r.planStatus} /> },
            {
              key: 'action',
              label: '처리',
              render: (r) => r.planStatus === '기안'
                ? <button type={'button'} onClick={(e) => { e.stopPropagation(); setTarget(r); setMode('submit'); }}>상신</button>
                : null,
            },
          ]}
        />
        <Pager page={pageNo} size={plans.data?.size ?? 20} total={plans.data?.total ?? 0} onPage={setPageNo} />
      </section>

      <section className={'box span-4'}>
        <h2>최근 연차촉진</h2>
        <Band total={promotions.data?.total}>
          <button type={'button'} onClick={() => setMode('promo')}>촉진 실행</button>
        </Band>
        {promotions.error ? <ErrorLine text={promotions.error} /> : null}
        <DataTable
          rows={promoRows}
          empty={'촉진 내역이 없습니다.'}
          columns={[
            { key: 'employeeId', label: '대상', render: (r) => <RefName table={'employee'} role={role} value={r.employeeId} /> },
            { key: 'promotionStage', label: '단계' },
            { key: 'noticeDate', label: '통보일', render: (r) => <DateText value={r.noticeDate} /> },
            { key: 'usedDays', label: '사용 일수', render: (r) => <Num value={r.usedDays} /> },
          ]}
        />
      </section>

      {mode === 'create' ? (
        <Drawer title={'연차계획 등록'} onClose={close}>
          <Form onSubmit={createPlan} submit={'등록'}>
            <Field label={'임직원'} required>
              <LookupSelect table={'employee'} role={role} value={employeeId} onChange={setEmployeeId} />
            </Field>
            <Field label={'계획 연월'} required hint={'YYYY-MM'}>
              <TextInput value={month} onChange={setMonth} placeholder={'YYYY-MM'} />
            </Field>
            <Field label={'계획 일자'} required>
              <DateInput value={planDate} onChange={setPlanDate} />
            </Field>
          </Form>
        </Drawer>
      ) : null}

      {mode === 'submit' && target ? (
        <Drawer title={'연차계획 결재 상신'} onClose={close}>
          <Form onSubmit={submitPlan} submit={'상신'} note={'기안 상태의 연차계획을 전자결재로 상신합니다.'}>
            <Field label={'임직원'}>
              <RefName table={'employee'} role={role} value={target.employeeId} />
            </Field>
            <Field label={'계획 일자'}>
              <DateText value={target.planDate} />
            </Field>
          </Form>
        </Drawer>
      ) : null}

      {mode === 'result' ? (
        <Drawer title={'결재 결과 반영'} onClose={close}>
          <Form onSubmit={reflectResult} submit={'반영'}>
            <Field label={'결재문서'} required>
              <LookupSelect table={'approval_document'} role={role} value={docId} onChange={setDocId} />
            </Field>
            <Field label={'계획 상태'} required>
              <Select value={resultStatus} onChange={setResultStatus} options={STATUS_OPTIONS} />
            </Field>
          </Form>
        </Drawer>
      ) : null}

      {mode === 'promo' ? (
        <Drawer title={'연차촉진 실행'} onClose={close}>
          <Form onSubmit={createPromotion} submit={'실행'}>
            <Field label={'연차'} required>
              <LookupSelect table={'annual_leave'} role={role} value={annualLeaveId} onChange={setAnnualLeaveId} />
            </Field>
            <Field label={'촉진 대상 임직원'} required>
              <LookupSelect table={'employee'} role={role} value={promoEmployeeId} onChange={setPromoEmployeeId} />
            </Field>
            <Field label={'촉진 단계'} required>
              <Select value={stage} onChange={setStage} options={STAGE_OPTIONS} />
            </Field>
            <Field label={'통보일'} required>
              <DateInput value={noticeDate} onChange={setNoticeDate} />
            </Field>
          </Form>
        </Drawer>
      ) : null}
    </div>
  );
}
